import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";var i=JSON.parse(`{"title":"更新・バックアップ・復旧","description":"","frontmatter":{},"headers":[],"relativePath":"operations/maintenance.md","filePath":"operations/maintenance.md","lastUpdated":1793464466000}`),a={name:`operations/maintenance.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="更新・バックアップ・復旧" tabindex="-1">更新・バックアップ・復旧 <a class="header-anchor" href="#更新・バックアップ・復旧" aria-label="Permalink to “更新・バックアップ・復旧”">​</a></h1><h2 id="更新の基本" tabindex="-1">更新の基本 <a class="header-anchor" href="#更新の基本" aria-label="Permalink to “更新の基本”">​</a></h2><p>実装をコミットし、テスト後にPreviewへ配置します。確認が終わったコミットを指定して本番リリースします。<a href="./../getting-started/preview-production">更新のコマンド</a>を参照してください。</p><p>施策や共通デザインの変更は管理画面で行います。下書き保存、施策の配信開始、システム全体のデプロイは別の操作です。</p><h2 id="バックアップ" tabindex="-1">バックアップ <a class="header-anchor" href="#バックアップ" aria-label="Permalink to “バックアップ”">​</a></h2><p>CloudflareではD1のTime Travel復旧位置とコードのコミットを控え、必要に応じてエクスポートします。</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> d1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DB</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --remote</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup.sql</span></span></code></pre></div><p>管理用DBには設定だけでなく、メール、パスキー公開鍵、セッション、招待等の情報も含みます。バックアップへのアクセスを制限してください。</p><p>Node.jsではSQLite本体とWALの整合性を保ちます。停止中またはSQLite対応のバックアップ方法を使い、永続ディスクを確保します。</p><p>閲覧者の行動履歴をサーバーからバックアップ・復元する機能はありません。</p><h2 id="旧管理トークン方式から移行する" tabindex="-1">旧管理トークン方式から移行する <a class="header-anchor" href="#旧管理トークン方式から移行する" aria-label="Permalink to “旧管理トークン方式から移行する”">​</a></h2><p>追加マイグレーションで管理テーブルを作ります。既存app_configを削除せず、最初のSuperuser登録の成功時にその時点の最新サイトをコピーします。サイト・施策IDと既存質問は維持します。</p><p>切り替え後はadmin_sitesを使い、旧app_configの更新を凍結します。旧トークンで通常の管理APIへ入れません。AUTH_MODEを消しても旧方式へ自動復帰しません。</p><h2 id="切り戻し" tabindex="-1">切り戻し <a class="header-anchor" href="#切り戻し" aria-label="Permalink to “切り戻し”">​</a></h2><p>コードだけを古い版へ戻すと、DBの新しい設定と整合しないことがあります。追加移行を維持した修正版への更新を優先します。</p><p>過去へ戻す場合はメンテナンス中にコードとDBの復旧位置をそろえ、失われる管理操作を確認します。質問を無断で切り詰めて古い形式へ変換しないでください。</p><h2 id="アカウントの復旧" tabindex="-1">アカウントの復旧 <a class="header-anchor" href="#アカウントの復旧" aria-label="Permalink to “アカウントの復旧”">​</a></h2><p>通常は予備パスキー、復旧コード、Superuserの期限付き復旧リンクを使います。<a href="./../guides/accounts">アカウント</a>を参照してください。</p><p>全Superuserが資格を失った場合は、DBを操作できる環境運用者が、本人確認とバックアップを行って対応します。ADMIN_TOKENで既存アカウントを取り直す公開の裏口はありません。運用者向けの最終手順は<a href="https://github.com/manji6/jev-personalization/blob/feature/admin-v2-implementation/docs/admin-v2-setup.md" target="_blank" rel="noreferrer">リポジトリの移行・復旧手順</a>に記載しています。</p><h2 id="稼働確認" tabindex="-1">稼働確認 <a class="header-anchor" href="#稼働確認" aria-label="Permalink to “稼働確認”">​</a></h2><p><code>/health</code>はプロセスの応答確認です。Jevの残高、正しい対象者判定、すべてのSecretの有効性を保証しません。PreviewではAccessにより入口も保護されます。</p><p>モデル障害・混雑・費用上限ではオファーを出さずに継続します。対象サイト本体の操作ができることと、診断パネルの理由を確認してください。</p>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};